/** Set the tier (hot/warm/cold) of an entry. Pure. */
export function setTier(doc, kind, id, tier) {
  const d = doc && isValidMemory(doc) ? structuredClone(doc) : emptyMemory();
  if (!["hot", "warm", "cold"].includes(tier)) throw new Error("tier must be hot|warm|cold");
  const list = kind === "lesson" ? d.lessons : kind === "workflow" ? d.workflows : kind === "convention" ? d.projectConventions : null;
  if (!list) throw new Error("kind must be lesson|workflow|convention");
  const e = list.find((x) => x.id === id);
  if (!e) throw new Error("entry not found: " + id);
  e.tier = tier;
  d.updatedAt = new Date().toISOString();
  d.changelog.push({ ts: d.updatedAt, action: "tier", path: kind + ":" + id, summary: tier });
  return d;
}

/** Copy a doc with sensitive preference values redacted. Pure. */
export function redactDoc(doc, sensitiveKeys = []) {
  const d = doc && isValidMemory(doc) ? structuredClone(doc) : emptyMemory();
  const keys = new Set(sensitiveKeys);
  for (const k of Object.keys(d.preferences || {})) {
    if (keys.has(k)) d.preferences[k] = "[redacted]";
  }
  return d;
}

/** Build a human-readable audit report from a doc + expected integrity. Pure. */
export function auditReport(doc, expectedHash, actualHash) {
  const d = doc && isValidMemory(doc) ? doc : emptyMemory();
  const out = [];
  out.push("Memory audit");
  out.push("- integrity: " + (expectedHash && actualHash === expectedHash ? "OK (" + actualHash.slice(0, 12) + ")" : actualHash ? "MISMATCH (expected " + String(expectedHash).slice(0, 12) + ", got " + actualHash.slice(0, 12) + ")" : "not tracked"));
  out.push("- schemaVersion: " + (d.schemaVersion || 1));
  out.push("- entries: " + (Object.values(d.preferences || {}).filter((x) => String(x).trim()).length + (d.projectConventions || []).length + (d.workflows || []).length + (d.lessons || []).length));
  out.push("- changelog entries: " + (d.changelog || []).length);
  for (const c of (d.changelog || []).slice(-20)) out.push("  - " + (c.ts || "?") + " [" + c.action + "] " + c.path + ": " + c.summary);
  return out.join("\n");
}

// ---- v1.1: CLAUDE.md import ----

/** Parse CLAUDE.md-style text into convention details. Pure. */
export function parseClaudeMd(text) {
  const out = [];
  for (const raw of String(text).split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || /^#/.test(line)) continue;
    const item = line.replace(/^[-*]\s*/, "").trim();
    if (item && item.length >= 8) out.push({ type: "imported", pattern: "claude-md", detail: item, evidence: "CLAUDE.md" });
  }
  return out;
}

// ---- v1.2: annotations + bundle ----

/** Annotate an entry with owner/purpose. Pure. */
export function annotateEntry(doc, kind, id, fields) {
  const d = doc && isValidMemory(doc) ? structuredClone(doc) : emptyMemory();
  const list = kind === "lesson" ? d.lessons : kind === "workflow" ? d.workflows : kind === "convention" ? d.projectConventions : null;
  if (!list) throw new Error("kind must be lesson|workflow|convention");
  const e = list.find((x) => x.id === id);
  if (!e) throw new Error("entry not found: " + id);
  if (fields.owner) e.owner = fields.owner;
  if (fields.purpose) e.purpose = fields.purpose;
  d.updatedAt = new Date().toISOString();
  d.changelog.push({ ts: d.updatedAt, action: "annotate", path: kind + ":" + id, summary: fields.owner || fields.purpose || "" });
  return d;
}

/** Bundle memory + knowledge + snapshots index into one object. Pure. */
export function buildBundle(doc, kb, snapshots, extra = {}) {
  return { bundleVersion: 1, exportedAt: new Date().toISOString(), memory: migrateMemory(doc), knowledge: kb, snapshots: snapshots || [], ...extra };
}

/** Validate a bundle payload. Pure. */
export function parseBundle(text) {
  let p;
  try { p = JSON.parse(text); } catch { throw new Error("invalid JSON"); }
  if (!p || p.bundleVersion !== 1 || !isValidMemory(migrateMemory(p.memory))) throw new Error("not a valid bundle");
  return p;
}




